ode": "FAM:SF-APPA-050"}]}, {"id": "FAM:SF-APPS-014", "label": "Study family SF-APPS-014: Within-game DRIVE decline by game third", "score": 0.295, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-014 (0.20)", "request matches RQC:RQC-074 (0.15); FAM:SF-APPS-014 auto_addresses_question RQC:RQC-074"], "attributes": {"observed_research_question": "Within-game DRIVE decline by game third", "auto_outcome_status": "rejected", "observed_hypothesis": "DRIVE efficiency drops within a single playoff game (defense moves first) before cross-game adaptation.", "observed_result": "Game 1 DRIVE 0.864 (n=323) -> 0.942 (n=346), +0.078; all games 0.880 (n=1746) -> 0.973 (n=1987), +0.093.", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "DRIVE rises early-to-late (+0.078 G1, +0.093 all games) instead of dropping.", "observed_sample_and_power": "n=1746-1987 per third (all games)", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Pooled playoff possessions split into game thirds by elapsed time; Game 1 only and all games.", "observed_verdict": "reversed", "observed_failure_type": "B_powered_null", "observed_notes": "NOT_RECORDED", "auto_confidence": "high (0.95)"}, "relationships": [{"rel": "auto_addresses_question", "node": "RQC:RQC-074"}]}], "n_results": 4}

